1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"io"
7		"os"
8		"path/filepath"
9		"strings"
10	
11		"github.com/entireio/entire-brain/internal/cli/internal/base"
12		"github.com/spf13/cobra"
13	)
14	
15	type pathCommandOptions struct {
16		checkpointLimit int
17		entireBinary    string
18		rawTranscript   bool
19		scope           string
20		// ensure opts INTO building a missing brain. It is off by default because
21		// `path` is a getter: it answers "where does this repository's brain live".
22		// It used to refresh a missing brain unconditionally, so a single read-only
23		// question against an empty store wrote a seed corpus, a docs FTS index, a
24		// pattern corpus, a manifest and a lock directory -- and in a directory git
25		// could not answer for, it failed inside that build with a raw
26		// `fatal: not a git repository` from a subprocess the caller never asked for.
27		ensure bool
28	}
29	
30	func newPathCommand(opts Options) *cobra.Command {
31		pathOpts := pathCommandOptions{
32			checkpointLimit: defaultCheckpointLimit,
33			entireBinary:    "entire",
34			scope:           exportScopeAll,
35		}
36	
37		cmd := &cobra.Command{
38			Use:   "path [path-or-repo-url]",
39			Short: "Print the persistent brain path for a repo path or URL",
40			Long: `Path prints the persistent brain export directory for a repository.
41	
42	Path is a getter: by default it writes nothing. It resolves the target -- an
43	existing local path to its containing git worktree, a repo URL to its
44	deterministic brain directory -- and prints where that repository's brain
45	lives. The directory is printed whether or not the brain has been built yet;
46	build it with "setup" or "refresh", or pass --ensure to build a missing brain
47	here.`,
48			Args: cobra.MaximumNArgs(1),
49			RunE: func(cmd *cobra.Command, args []string) error {
50				target := "."
51				if opts.Env.RepoRoot != "" {
52					target = opts.Env.RepoRoot
53				}
54				if len(args) == 1 {
55					target = args[0]
56				}
57				return runPath(cmd.Context(), cmd, opts, pathOpts, target)
58			},
59		}
60	
61		cmd.Flags().BoolVar(&pathOpts.ensure, "ensure", false, "Build the brain when it is missing instead of only printing where it would live")
62		cmd.Flags().IntVar(&pathOpts.checkpointLimit, "checkpoint-limit", defaultCheckpointLimit, "Maximum checkpoints to inspect when building with --ensure (0 means all)")
63		cmd.Flags().StringVar(&pathOpts.entireBinary, "entire-binary", "entire", "Entire CLI binary to invoke when building with --ensure")
64		cmd.Flags().BoolVar(&pathOpts.rawTranscript, "raw", false, "Export raw agent transcripts instead of normalized compact transcripts when building with --ensure")
65		cmd.Flags().StringVar(&pathOpts.scope, "scope", exportScopeAll, "Checkpoint discovery scope when building with --ensure: all or branch")
66	
67		return cmd
68	}
69	
70	func runPath(ctx context.Context, cmd *cobra.Command, opts Options, pathOpts pathCommandOptions, target string) error {
71		slugForHost := lookupRepoDomainSlug
72		if pathOpts.ensure {
73			slugForHost = repoDomainSlug
74		}
75		dirs, err := base.ResolvePluginDirs(opts.Env)
76		if err != nil {
77			return err
78		}
79	
80		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
81		if err != nil {
82			if looksLikeWindowsDriveTargetPath(target) {
83				return err
84			}
85			key, ok, keyErr := repoKeyFromRemoteWithSlug(dirs.Config, target, slugForHost)
86			if keyErr != nil {
87				return keyErr
88			}
89			if !ok {
90				return err
91			}
92			brainDir, dirErr := base.BrainDirForKey(opts.Env, key)
93			if dirErr != nil {
94				return dirErr
95			}
96			fmt.Fprintln(cmd.OutOrStdout(), brainDir)
97			return nil
98		}
99		if local {
100			set, err := resolveRepoStorageSetWithSlug(ctx, opts.Runner, opts.Env, repoDir, slugForHost)
101			if err != nil {
102				return err
103			}
104			if err := set.conflictError(); err != nil {
105				return err
106			}
107			storage := set.Active()
108			if err := checkPathTargetIsAddressable(ctx, opts, storage, repoDir); err != nil {
109				return err
110			}
111			if pathOpts.ensure && !brainExportExists(storage.BrainDir) {
112				if err := pathOpts.validateForEnsure(); err != nil {
113					return err
114				}
115				if err := runPathRefresh(ctx, opts, pathOpts, repoDir); err != nil {
116					return err
117				}
118			}
119			fmt.Fprintln(cmd.OutOrStdout(), storage.BrainDir)
120			return nil
121		}
122	
123		if looksLikeWindowsDriveTargetPath(target) {
124			return fmt.Errorf("target is neither an existing path nor a supported repo URL: %s", target)
125		}
126		key, ok, err := repoKeyFromRemoteWithSlug(dirs.Config, target, slugForHost)
127		if err != nil {
128			return err
129		}
130		if ok {
131			// brainDirForKey rather than a raw join: `brain path` must print the
132			// location every other command would actually use, which means it has to
133			// answer to the same reserved-segment and symlink refusals. A path this
134			// helper refuses is one no other verb will read or write, so printing it
135			// hands the caller a location the tool does not honour.
136			brainDir, dirErr := base.BrainDirForKey(opts.Env, key)
137			if dirErr != nil {
138				return dirErr
139			}
140			fmt.Fprintln(cmd.OutOrStdout(), brainDir)
141			return nil
142		}
143		return fmt.Errorf("target is neither an existing path nor a supported repo URL: %s", target)
144	}
145	
146	// checkPathTargetIsAddressable refuses a local target git cannot answer for,
147	// UNLESS a brain is already stored for it.
148	//
149	// resolveLocalTargetRepoDir deliberately tolerates a non-repository, so without
150	// this check `path` printed a brain directory derived from a path hash for any
151	// directory at all -- a location `refresh` can never populate, because every
152	// source the brain is built from is read out of git. Printing it made a
153	// `BRAIN=$(entire brain path)` caller believe it had an answer. The existing-brain
154	// exemption keeps a brain reachable after its worktree loses .git, which is
155	// exactly when a reader needs to find it.
156	func checkPathTargetIsAddressable(ctx context.Context, opts Options, storage repoStorage, repoDir string) error {
157		if _, ok := gitWorkTreeRoot(ctx, opts.Runner, repoDir); ok {
158			return nil
159		}
160		stored, err := repoStorageContainsState(storage)
161		if err != nil {
162			return err
163		}
164		if stored {
165			return nil
166		}
167		brainCmd := base.SetupCommandPrefix(os.LookupEnv)
168		return notARepositoryError(ctx, opts.Runner, repoDir,
169			brainCmd+" path reports where a repository's brain lives, and a repository's identity -- like every source its brain is built from -- comes from git.",
170			brainCmd+" path",
171			brainCmd+" path <path-or-repo-url>")
172	}
173	
174	// validateForEnsure checks the build flags, which are only read when --ensure
175	// actually builds something.
176	func (o pathCommandOptions) validateForEnsure() error {
177		if o.checkpointLimit < 0 {
178			return fmt.Errorf("--checkpoint-limit must be greater than or equal to zero")
179		}
180		if strings.TrimSpace(o.entireBinary) == "" {
181			return fmt.Errorf("--entire-binary must not be empty")
182		}
183		if o.scope != exportScopeAll && o.scope != exportScopeBranch {
184			return fmt.Errorf("--scope must be either all or branch")
185		}
186		return nil
187	}
188	
189	func looksLikeWindowsDrivePath(target string) bool {
190		return len(target) >= 2 &&
191			((target[0] >= 'A' && target[0] <= 'Z') || (target[0] >= 'a' && target[0] <= 'z')) &&
192			target[1] == ':'
193	}
194	
195	func looksLikeWindowsDriveTargetPath(target string) bool {
196		if !looksLikeWindowsDrivePath(target) {
197			return false
198		}
199		if match := repoRemoteSCPRegex.FindStringSubmatch(target); len(match) == 3 && !looksLikeWindowsDriveRemotePath(target, match[2]) {
200			return false
201		}
202		return true
203	}
204	
205	// gitWorkTreeRoot reports the work-tree root git resolves for dir, and whether
206	// dir is inside a git work tree at all.
207	//
208	// resolveLocalTargetRepoDir deliberately TOLERATES a non-repository (a path is
209	// still a path, and workspace members keep path hints for repos that are not
210	// present yet), so the callers that REQUIRE a repository have to ask for
211	// themselves. Without this, `setup` in a plain directory discovered the answer
212	// one component at a time, as four separate raw `fatal: not a git repository`
213	// subprocess failures, after it had already registered a workspace and
214	// installed a background watcher.
215	func gitWorkTreeRoot(ctx context.Context, runner CommandRunner, dir string) (string, bool) {
216		if runner == nil || strings.TrimSpace(dir) == "" {
217			return "", false
218		}
219		stdout, _, err := runner.Run(ctx, dir, "git", "rev-parse", "--show-toplevel")
220		if err != nil {
221			return "", false
222		}
223		root := strings.TrimSpace(string(stdout))
224		if root == "" {
225			return "", false
226		}
227		return filepath.Clean(root), true
228	}
229	
230	// notARepositoryError names the RIGHT failure when gitWorkTreeRoot says no.
231	//
232	// `git rev-parse --show-toplevel` fails for two unrelated reasons, and they are
233	// indistinguishable from the caller's side: the directory is not a repository,
234	// or `git` could not be run at all. Every caller read the failure as the first,
235	// so a machine with no git in PATH was told "not a git repository: <a perfectly
236	// good repository>" and handed `git init` as the remedy -- advice that needs the
237	// program that is missing. nameDegenerateRepoFailure already reasons this way
238	// about an unborn HEAD ("answering that with 'no commits yet' would be a
239	// confident wrong diagnosis"); the repo-ness gate simply never did.
240	//
241	// The probe is positive evidence, not inference: `git --version` succeeds or
242	// fails on git's presence alone -- it never reads a repository, so it cannot be
243	// confounded by the state of this directory. It runs only on a path that has
244	// already failed, so a healthy repo pays nothing for it.
245	//
246	// `needsGit` is the sentence naming why git is needed. The two remedies are
247	// separate on purpose: with git missing the reader has nothing to change about
248	// this directory and simply re-runs `rerun` once git is installed, while with
249	// git present the directory is the problem and `elsewhere` is how they name a
250	// different one.
251	func notARepositoryError(ctx context.Context, runner CommandRunner, repoDir, needsGit, rerun, elsewhere string) error {
252		if !commandLooksAvailable(ctx, runner, repoDir, "git") {
253			return fmt.Errorf("git is not available: %s\n"+
254				"%s\n"+
255				"install git and put it on PATH, then re-run `%s`", repoDir, needsGit, rerun)
256		}
257		return fmt.Errorf("not a git repository: %s\n"+
258			"%s\n"+
259			"run `git init` here and make at least one commit, or name a repository: %s", repoDir, needsGit, elsewhere)
260	}
261	
262	// firstErrorLine is an error reduced to its opening line, for the one-line
263	// slots -- progress notes, status axes -- that a multi-line named condition
264	// would otherwise wrap into nonsense.
265	func firstErrorLine(err error) string {
266		if err == nil {
267			return ""
268		}
269		text := err.Error()
270		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
271			return text[:idx]
272		}
273		return text
274	}
275	
276	// nameDegenerateRepoFailure replaces a raw git failure with the repository
277	// condition that explains it.
278	//
279	// A brain command run against a repository with no commits exited 1 -- the right
280	// code -- while printing whichever git subprocess happened to notice first,
281	// verbatim, including the hardening flags this binary adds and the caller never
282	// typed:
283	//
284	//	resolve HEAD for semantic index: git [-c core.fsmonitor=false rev-parse HEAD]:
285	//	exit status 128: fatal: ambiguous argument 'HEAD': unknown revision or path
286	//	not in the working tree.
287	//
288	// Only the conditions one further probe settles are named: no work tree at all,
289	// a bare repository, and an unborn HEAD. A detached HEAD and a shallow clone are
290	// deliberately absent -- both build a brain, and the surfaces that care already
291	// describe them (branch_tip=stale, and the shallow-boundary warning entityindex
292	// raises) -- and every other failure keeps git's own text, which is worth more
293	// than a guess.
294	//
295	// The probes run only on a path that has already failed, so a healthy repo pays
296	// nothing for them.
297	func nameDegenerateRepoFailure(ctx context.Context, runner CommandRunner, repoDir string, err error) error {
298		if err == nil || runner == nil {
299			return err
300		}
301		brainCmd := base.SetupCommandPrefix(os.LookupEnv)
302		if _, ok := gitWorkTreeRoot(ctx, runner, repoDir); !ok {
303			if bare, bareErr := base.GitScalar(ctx, runner, repoDir, "rev-parse", "--is-bare-repository"); bareErr == nil && strings.TrimSpace(bare) == "true" {
304				return fmt.Errorf("bare repository has no working tree: %s\n"+
305					"%[2]s reads seed, docs and the code index out of a working tree, and a bare repository has none.\n"+
306					"point it at a clone with a checkout: %[2]s refresh <path>", repoDir, brainCmd)
307			}
308			return notARepositoryError(ctx, runner, repoDir,
309				brainCmd+" builds every source it has -- sessions, seed, docs, code index -- from git history, so it needs git and a repository.",
310				brainCmd+" refresh",
311				brainCmd+" refresh <path>")
312		}
313		// An unborn HEAD has to be shown, not inferred from the failure that got us
314		// here: `git rev-parse HEAD` also fails when git itself is unavailable, and
315		// answering that with "no commits yet" would be a confident wrong diagnosis.
316		//
317		// symbolic-ref SUCCEEDING is the positive evidence -- it proves git ran and
318		// the repo is readable, and it returns the branch HEAD points at even when
319		// that branch has no commit. If that branch then does not resolve, the only
320		// thing left is that nothing has been committed to it. A detached HEAD has
321		// no symbolic ref and falls through here untouched, which is correct: it is
322		// not a condition this names.
323		ref, refErr := base.GitScalar(ctx, runner, repoDir, "symbolic-ref", "--quiet", "HEAD")
324		if refErr != nil || strings.TrimSpace(ref) == "" {
325			return err
326		}
327		if _, resolved := base.GitScalar(ctx, runner, repoDir, "rev-parse", "--verify", "--quiet", strings.TrimSpace(ref)); resolved == nil {
328			return err
329		}
330		return fmt.Errorf("this repository has no commits yet: %s\n"+
331			"%[2]s pins every source it builds to a commit, and an unborn branch has none.\n"+
332			"make at least one commit, then run `%[2]s refresh` again", repoDir, brainCmd)
333	}
334	
335	func brainExportExists(brainDir string) bool {
336		info, err := os.Stat(filepath.Join(brainDir, exportManifestFileName))
337		return err == nil && !info.IsDir()
338	}
339	
340	func runPathRefresh(ctx context.Context, opts Options, pathOpts pathCommandOptions, repoDir string) error {
341		refreshCmd := &cobra.Command{Use: "refresh"}
342		refreshCmd.SetOut(io.Discard)
343		refreshCmd.SetErr(io.Discard)
344		refreshEnv := opts.Env
345		refreshEnv.RepoRoot = repoDir
346		return runRefresh(ctx, refreshCmd, Options{
347			Version: opts.Version,
348			Env:     refreshEnv,
349			Runner:  opts.Runner,
350			Now:     opts.Now,
351		}, refreshCommandOptions{
352			checkpointLimit: pathOpts.checkpointLimit,
353			entireBinary:    pathOpts.entireBinary,
354			rawTranscript:   pathOpts.rawTranscript,
355			scope:           pathOpts.scope,
356			seed: seedCommandOptions{
357				includeTests:       true,
358				maxFileBytes:       defaultSeedMaxFileBytes,
359				maxFiles:           defaultSeedMaxFiles,
360				format:             "markdown+json",
361				agent:              "none",
362				agentTimeoutAction: "keep-quick",
363				agentMaxInputBytes: defaultAgentMaxInput,
364			},
365		})
366	}
