230	// notARepositoryError names the RIGHT failure when gitWorkTreeRoot says no.
231	//
232	// `git rev-parse --show-toplevel` fails for two unrelated reasons, and they are
233	// indistinguishable from the caller's side: the directory is not a repository,
234	// or `git` could not be run at all. Every caller read the failure as the first,
235	// so a machine with no git in PATH was told "not a git repository: <a perfectly
236	// good repository>" and handed `git init` as the remedy -- advice that needs the
237	// program that is missing. nameDegenerateRepoFailure already reasons this way
238	// about an unborn HEAD ("answering that with 'no commits yet' would be a
239	// confident wrong diagnosis"); the repo-ness gate simply never did.
240	//
241	// The probe is positive evidence, not inference: `git --version` succeeds or
242	// fails on git's presence alone -- it never reads a repository, so it cannot be
243	// confounded by the state of this directory. It runs only on a path that has
244	// already failed, so a healthy repo pays nothing for it.
245	//
246	// `needsGit` is the sentence naming why git is needed. The two remedies are
247	// separate on purpose: with git missing the reader has nothing to change about
248	// this directory and simply re-runs `rerun` once git is installed, while with
249	// git present the directory is the problem and `elsewhere` is how they name a
250	// different one.
251	func notARepositoryError(ctx context.Context, runner CommandRunner, repoDir, needsGit, rerun, elsewhere string) error {
252		if !commandLooksAvailable(ctx, runner, repoDir, "git") {
253			return fmt.Errorf("git is not available: %s\n"+
254				"%s\n"+
255				"install git and put it on PATH, then re-run `%s`", repoDir, needsGit, rerun)
256		}
257		return fmt.Errorf("not a git repository: %s\n"+
258			"%s\n"+
259			"run `git init` here and make at least one commit, or name a repository: %s", repoDir, needsGit, elsewhere)
260	}
