262	// firstErrorLine is an error reduced to its opening line, for the one-line
263	// slots -- progress notes, status axes -- that a multi-line named condition
264	// would otherwise wrap into nonsense.
265	func firstErrorLine(err error) string {
266		if err == nil {
267			return ""
268		}
269		text := err.Error()
270		if idx := strings.IndexByte(text, '\n'); idx >= 0 {
271			return text[:idx]
272		}
273		return text
274	}
